const ROOM_DOORS=[[0,180,300,60,240],[0,180,240,120],[0,180,60,240],[180,60,120]];
const SEGS2:number[][]=[[ROOMS[0],0,-9,ANNEX[0].x,ANNEX[0].z,-8.6],[ANNEX[0].x,ANNEX[0].z,-8.6,ROOMS[1],0,-8.2],[ROOMS[3],0,-8.2,ANNEX[1].x,ANNEX[1].z,-8.2],[ANNEX[1].x,ANNEX[1].z,-8.2,ANNEX[2].x,ANNEX[2].z,-8.2],[ANNEX[2].x,ANNEX[2].z,-8.2,ANNEX[3].x,ANNEX[3].z,-8.2],[ROOMS[2],0,-8.6,ANNEX[4].x,ANNEX[4].z,-8.2],[ANNEX[4].x,ANNEX[4].z,-8.2,ROOMS[3],0,-8.2],[ROOMS[2],0,-8.6,ANNEX[5].x,ANNEX[5].z,-8.4],[ANNEX[5].x,ANNEX[5].z,-8.4,ANNEX[0].x,ANNEX[0].z,-8.6],[ANNEX[6].x,ANNEX[6].z,-8.2,ANNEX[8].x,ANNEX[8].z,-8.2],[ANNEX[8].x,ANNEX[8].z,-8.2,ANNEX[2].x,ANNEX[2].z,-8.2],[ANNEX[3].x,ANNEX[3].z,-8.2,ANNEX[8].x,ANNEX[8].z,-8.2],[ANNEX[7].x,ANNEX[7].z,-8.2,ROOMS[0],0,-9],[ANNEX[7].x,ANNEX[7].z,-8.2,ROOMS[1],0,-8.2],[ANNEX[7].x,ANNEX[7].z,-8.2,ANNEX[6].x,ANNEX[6].z,-8.2],[ANNEX[9].x,ANNEX[9].z,-9.2,ANNEX[10].x,ANNEX[10].z,-8.6],[ANNEX[9].x,ANNEX[9].z,-9.2,ANNEX[11].x,ANNEX[11].z,-8.6],[ANNEX[10].x,ANNEX[10].z,-8.6,ANNEX[0].x,ANNEX[0].z,-8.6],[ANNEX[11].x,ANNEX[11].z,-8.6,ANNEX[0].x,ANNEX[0].z,-8.6],[ANNEX[10].x,ANNEX[10].z,-8.6,ANNEX[11].x,ANNEX[11].z,-8.6],[ANNEX[10].x,ANNEX[10].z,-8.6,ROOMS[0],0,-9]];
const hexIn=(x:number,z:number,cx:number,cz:number,r:number)=>{const dx=x-cx,dz=z-cz;return Math.max(Math.abs(dx),Math.abs(.5*dx+.8660254*dz),Math.abs(.5*dx-.8660254*dz))<r*.8660254};
const segInfo=(x:number,z:number)=>{let best={d:1e9,y:0};for(const [ax,az,fa,bx,bz,fb] of SEGS2){const dx=bx-ax,dz=bz-az,l2=dx*dx+dz*dz,t=Math.max(0,Math.min(1,((x-ax)*dx+(z-az)*dz)/l2)),d=Math.hypot(x-ax-t*dx,z-az-t*dz);if(d<best.d)best={d,y:fa+(fb-fa)*t};}return best};
export function reviewFloorAt(x:number,z:number){for(const a of ANNEX)if(hexIn(x,z,a.x,a.z,REVIEW.radius))return a.fy;const sg=segInfo(x,z);if(sg.d<1.7)return sg.y;return reviewFloor(x);}
const CENTERS:number[][]=[...ALL_ROOMS.map(x=>[x,0]),...ANNEX.map(a=>[a.x,a.z])];
const ALL_LABELS=[...ROOM_LABELS,...ANNEX.map(a=>a.name)];
const nearest2=(x:number,z:number)=>CENTERS.reduce((b,c,k)=>Math.hypot(x-c[0],z-c[1])<Math.hypot(x-CENTERS[b][0],z-CENTERS[b][1])?k:b,0);
const MAPMID=[(Math.min(...CENTERS.map(c=>c[0]))+Math.max(...CENTERS.map(c=>c[0])))/2,(Math.min(...CENTERS.map(c=>c[1]))+Math.max(...CENTERS.map(c=>c[1])))/2];
const nearestRoom=(x:number)=>ALL_ROOMS.reduce((b,c,k)=>Math.abs(x-c)<Math.abs(x-ALL_ROOMS[b])?k:b,0);
const seams=ALL_ROOMS.slice(1).map((c,k)=>(c+ALL_ROOMS[k])/2);
const MID=(ALL_ROOMS[0]+ALL_ROOMS[ALL_ROOMS.length-1])/2;
export const reviewLift=(cx:number)=>({x:cx,z:cx===REVIEW.left?2.7:1.8});
const ANNEX_LIFT_THEMES=['library','search','pyramid'];const annexLift=(a:typeof ANNEX[number])=>({x:a.x,z:a.theme==='pyramid'?a.z-6.2:a.theme==='search'?a.z-3.6:a.z+3.6,fy:a.fy});
const LIFTS:{x:number;z:number;fy:number|null}[]=[...ROOMS.map(cx=>({...reviewLift(cx),fy:null as number|null})),...ANNEX.filter(a=>ANNEX_LIFT_THEMES.includes(a.theme)).map(annexLift)];
export function reviewFloor(x:number){return -9+THREE.MathUtils.clamp((x-(REVIEW.left+REVIEW.radius*.8660254))/(REVIEW.right-REVIEW.left-2*REVIEW.radius*.8660254),0,1)*.8;}
export function reviewWalkable(x:number,z:number){const inside=(cx:number)=>Math.max(Math.abs(x-cx),Math.abs(.5*(x-cx)+.8660254*z),Math.abs(.5*(x-cx)-.8660254*z))<(REVIEW.radius-.35)*.8660254;const column=ROOMS.some(cx=>[-3.3,3.3].some(dx=>[-3.4,3.4].some(dz=>Math.hypot(x-cx-dx,z-dz)<.6)));const pit=ROOMS.some(cx=>Math.abs(x-cx-3.2)<1.1&&z<-2.9&&z>-4.8);const shelf=inside(REVIEW.far)&&Math.abs(z)>1.75&&Math.abs(z)<3.45&&x>REVIEW.far-3.5&&x<REVIEW.far+2.4;const block=[[ANNEX[2].x,ANNEX[2].z,1.9],[ANNEX[3].x-2.2,ANNEX[3].z-1.5,.9],[ANNEX[3].x+2.2,ANNEX[3].z-1.5,.9],[ANNEX[3].x-2.2,ANNEX[3].z+1.8,.9],[ANNEX[3].x+2.2,ANNEX[3].z+1.8,.9]].some(([bx,bz,r])=>Math.hypot(x-bx,z-bz)<r);return !column&&!pit&&!shelf&&!block&&(ALL_ROOMS.some(inside)||ANNEX.some(a=>hexIn(x,z,a.x,a.z,REVIEW.radius-.35))||segInfo(x,z).d<1.35||x>REVIEW.far&&x<ROOMS[ROOMS.length-1]&&Math.abs(z)<1.35);}
